action_details.action_postfix:
// Physical nexus established - filing required
true result.ms_has_nexus xdef
"Mississippi filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.ms_has_nexus xdef
"Mississippi filing required: Economic nexus (exceeds $250,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Mississippi state additions
0.0 /ms_additions xdef

// Common Mississippi additions:
// - Federal bond interest
// - IRC 199A qualified business income deduction addback
// - State income taxes deducted federally

result.ms_us_interest_income 0.0 ne
{
  ms_additions result.ms_us_interest_income add /ms_additions xdef
} if

ms_additions result.ms_state_additions xdef

// Calculate Mississippi state subtractions
0.0 /ms_subtractions xdef

// Common Mississippi subtractions:
// - Mississippi municipal bond interest
// - Mississippi NOL deduction (5-year carryforward)
// - Dividend received deduction

result.ms_municipal_interest 0.0 ne
{
  ms_subtractions result.ms_municipal_interest add /ms_subtractions xdef
} if

ms_subtractions result.ms_state_subtractions xdef

"Mississippi additions: $" result.ms_state_additions cvs strconcat ", subtractions: $" strconcat result.ms_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Mississippi taxable income
// Federal taxable income apportioned to MS + additions - subtractions
result.ms_apportioned_income
result.ms_state_additions add
result.ms_state_subtractions sub
0.0 max
result.ms_taxable_income xdef

// Calculate Mississippi tax using graduated rates
0.0 /ms_tax xdef

// Tier 1: 3% on first $5,000
result.ms_taxable_income 5000.0 min result.ms_corp_tax_rate_tier1 mul
/ms_tier1_tax xdef
ms_tax ms_tier1_tax add /ms_tax xdef

// Tier 2: 4% on $5,001 to $10,000
result.ms_taxable_income 5000.0 >
{
  result.ms_taxable_income 10000.0 min 5000.0 sub
  result.ms_corp_tax_rate_tier2 mul
  /ms_tier2_tax xdef
  ms_tax ms_tier2_tax add /ms_tax xdef
} if

// Tier 3: 5% on income over $10,000
result.ms_taxable_income 10000.0 >
{
  result.ms_taxable_income 10000.0 sub
  result.ms_corp_tax_rate_tier3 mul
  /ms_tier3_tax xdef
  ms_tax ms_tier3_tax add /ms_tax xdef
} if

// Subtract Mississippi state credits (jobs creation, investment, R&D, film production, etc.)
ms_tax result.ms_state_credits sub 0.0 max
result.ms_tax_liability xdef

// Calculate refund or amount owed
result.ms_estimated_payments result.ms_tax_liability sub
result.ms_refund_or_owed xdef

"Mississippi taxable income: $" result.ms_taxable_income cvs strconcat job.audit_trail swap addto
"Mississippi tax liability (graduated rates 3%-5%): $" result.ms_tax_liability cvs strconcat job.audit_trail swap addto
